<script setup>
import {ref,computed} from 'vue';
import IconButton from './IconButton.vue';
import CodeEditor from './CodeEditor.vue';
import metadata from './processor-metadata.json';
const props=defineProps({modelValue:{type:Array,default:()=>[]},file:Boolean,sources:{type:Array,default:()=>[]}});const emit=defineEmits(['update:modelValue','preview']);
const selected=ref('');const clipboard=ref('');const status=ref('');const collapsed=ref({});const drag=ref(null);
const types=computed(()=>Object.entries(metadata).filter(([key])=>props.file?['Script Operator','Response Transformer','Add Proxies From Subscription Operator'].includes(key):!['Add Proxies From Subscription Operator'].includes(key)));
const clone=x=>JSON.parse(JSON.stringify(x));
const defaults={ 'Flag Operator':{mode:'add',tw:'cn'},'Sort Operator':'asc','Resolve Domain Operator':{provider:'Google',type:'IPv4',filter:'disabled',cache:'enabled',tlsSkipCertVerify:'disabled',url:'',edns:'',dnsConcurrency:'',concurrency:'',timeout:'',cacheTtl:''},'Region Filter':{keep:true,value:[]},'Type Filter':{keep:true,value:[]},'Regex Filter':{keep:true,regex:[]},'Regex Sort Operator':{order:'asc',expressions:[]},'Regex Rename Operator':[],'Regex Delete Operator':[],'Handle Duplicate Operator':{action:'rename',position:'back',template:'{{name}} {{index}}',link:'',field:['name']},'Add Proxies From Subscription Operator':{sourceType:'subscription',sourceName:'',includeUnsupportedProxy:false,position:'replace'}};
function update(list){emit('update:modelValue',list)}
function add(){const type=selected.value||types.value[0]?.[0];if(type)update([...props.modelValue,{id:crypto.randomUUID(),type,args:clone(defaults[type]??{mode:'link',content:'',arguments:{},noCache:false,insecure:false}),disabled:false}])}
function remove(i){update(props.modelValue.filter((_,n)=>n!==i))}
function move(i,j){if(j<0||j>=props.modelValue.length)return;const list=[...props.modelValue];list.splice(j,0,list.splice(i,1)[0]);update(list)}
async function copy(item){clipboard.value=JSON.stringify(item||props.modelValue,null,2);try{await navigator.clipboard.writeText(clipboard.value);status.value='已复制加工配置'}catch{status.value='配置已显示在导入框，可手动复制'}}
function paste(){try{const data=JSON.parse(clipboard.value);const list=Array.isArray(data)?data:[data];if(list.some(item=>!metadata[item.type]))throw Error();update([...props.modelValue,...list.map(item=>({...item,id:crypto.randomUUID()}))]);status.value='已导入加工配置'}catch{status.value='配置无效，请粘贴加工配置 JSON'}}
function lines(item,key,event){const value=event.trim()?event.split('\n'):[];if(key)item.args[key]=value;else item.args=value}
function script(item){return ['Script Operator','Script Filter','Response Transformer'].includes(item.type)}
const protocols=['ss','ssr','vmess','vless','trojan','http','h2-connect','socks5','snell','tuic','hysteria','hysteria2','juicity','mieru','sudoku','masque','masque-surge','shadowquic','naive','anytls','trusttunnel','openvpn','gost-relay','zerotier','tailscale','easytier','wireguard','ssh','external','direct'];
</script>
<template><section aria-label="加工链"><div class="resource-row"><h3>加工链</h3><IconButton label="复制全部加工配置" icon="faCopy" @activate="copy()"/><a class="card-link" href="https://github.com/sub-store-org/Sub-Store/wiki/脚本使用说明" target="_blank" rel="noopener">脚本文档 ↗</a></div><p class="field-note">按顺序处理。此设计稿可编辑参数，处理结果使用示例数据。</p><article v-for="(item,index) in modelValue" :key="item.id" class="processor-card" draggable="true" @dragstart.stop="drag=index" @dragover.prevent @drop.stop.prevent="move(drag,index)"><div class="processor-heading"><strong>{{ index+1 }}. {{item.customName||metadata[item.type]?.label}}</strong><IconButton label="向上移动" icon="faArrowUp" :disabled="index===0" @activate="move(index,index-1)"/><IconButton label="向下移动" icon="faArrowDown" :disabled="index===modelValue.length-1" @activate="move(index,index+1)"/><IconButton label="复制此步骤" icon="faCopy" @activate="copy(item)"/><IconButton label="预览此步骤" icon="faEye" @activate="emit('preview',index)"/><IconButton :label="collapsed[item.id]?'展开参数':'折叠参数'" :icon="collapsed[item.id]?'faExpand':'faCompress'" @activate="collapsed[item.id]=!collapsed[item.id]"/><IconButton label="删除此步骤" icon="faTrashCan" danger @activate="remove(index)"/></div><FormKit type="checkbox" :model-value="!item.disabled" label="启用此步骤" :ignore="true" @input="item.disabled=!$event"/><div v-show="!collapsed[item.id]"><FormKit type="text" v-model="item.customName" label="步骤名称" :ignore="true"/><p class="processor-description">{{metadata[item.type]?.tipsDes}}</p>
<template v-if="script(item)"><FormKit type="select" v-model="item.args.mode" :ignore="true" label="脚本来源" :options="{link:'远程脚本',script:'本地脚本'}"/><FormKit v-if="item.args.mode==='link'" type="url" v-model="item.args.content" :ignore="true" label="脚本地址"/><CodeEditor v-else v-model="item.args.content" language="javascript"/><FormKit v-if="item.args.mode==='link'" type="checkbox" v-model="item.args.noCache" :ignore="true" label="不使用缓存"/><FormKit v-if="item.args.mode==='link'" type="checkbox" v-model="item.args.insecure" :ignore="true" label="允许不安全 TLS"/><h4>脚本参数</h4><div v-for="(value,key) in item.args.arguments" :key="key" class="resource-row"><strong>{{key}}</strong><FormKit v-model="item.args.arguments[key]" :ignore="true" :label="'参数 '+key"/><IconButton label="删除参数" icon="faTrashCan" @activate="delete item.args.arguments[key]"/></div><FormKit type="text" v-model="item.newKey" :ignore="true" label="新参数名"/><button class="button" type="button" @click="item.newKey&&(item.args.arguments[item.newKey]='',item.newKey='')">添加参数</button></template>
<template v-else-if="item.type==='Flag Operator'"><FormKit v-model="item.args.mode" type="select" :ignore="true" label="旗帜处理" :options="{add:'添加',remove:'移除'}"/><FormKit v-model="item.args.tw" type="select" :ignore="true" label="台湾地区旗帜" :options="['cn','ws','tw']"/></template>
<FormKit v-else-if="item.type==='Sort Operator'" v-model="item.args" type="select" :ignore="true" label="排序方式" :options="{asc:'升序',desc:'降序',random:'随机'}"/>
<template v-else-if="item.type==='Resolve Domain Operator'"><FormKit v-model="item.args.provider" type="select" :ignore="true" label="解析服务" :options="['Google','IP-API','Cloudflare','Ali','Tencent','Custom']"/><FormKit v-if="item.args.provider==='Custom'" v-model="item.args.url" type="url" :ignore="true" label="自定义 DNS 地址"/><FormKit v-model="item.args.type" type="select" :ignore="true" label="解析地址类型" :options="['IPv4','IPv6']"/><FormKit v-model="item.args.filter" type="select" :ignore="true" label="解析后筛选" :options="{disabled:'不筛选',removeFailed:'移除解析失败',IPOnly:'只保留 IP',IPv4Only:'只保留 IPv4',IPv6Only:'只保留 IPv6'}"/><FormKit v-model="item.args.cache" type="select" :ignore="true" label="解析缓存" :options="{enabled:'启用',disabled:'禁用'}"/><FormKit v-model="item.args.tlsSkipCertVerify" type="select" :ignore="true" label="跳过证书验证" :options="{disabled:'否',enabled:'是'}"/><FormKit v-for="[key,label] in [['edns','EDNS 地址'],['dnsConcurrency','DNS 并发'],['concurrency','处理并发'],['timeout','超时（毫秒）'],['cacheTtl','缓存有效期（秒）']]" :key="key" v-model="item.args[key]" :ignore="true" :label="label"/></template>
<template v-else-if="['Region Filter','Type Filter'].includes(item.type)"><FormKit v-model="item.args.keep" type="select" :ignore="true" label="筛选方式" :options="[{label:'保留匹配',value:true},{label:'排除匹配',value:false}]"/><FormKit v-model="item.args.value" type="checkbox" :ignore="true" label="匹配范围" :options="item.type==='Region Filter'?['HK','TW','SG','JP','UK','US','DE','KR']:protocols"/></template>
<template v-else-if="item.type==='Handle Duplicate Operator'"><FormKit v-model="item.args.action" type="select" :ignore="true" label="重复节点处理" :options="{rename:'重命名',delete:'删除'}"/><FormKit type="textarea" :model-value="item.args.field.join('\n')" :ignore="true" label="比较字段（每行一个）" @input="lines(item,'field',$event)"/><template v-if="item.args.action==='rename'"><FormKit v-model="item.args.position" type="select" :ignore="true" label="序号位置" :options="{front:'前面',back:'后面'}"/><FormKit v-model="item.args.template" :ignore="true" label="重命名模板"/><FormKit v-model="item.args.link" :ignore="true" label="连接符"/></template></template>
<template v-else-if="item.type==='Add Proxies From Subscription Operator'"><FormKit v-model="item.args.sourceType" type="select" :ignore="true" label="来源类型" :options="{subscription:'单订阅',collection:'组合订阅'}"/><FormKit v-model="item.args.sourceName" type="select" :ignore="true" label="来源" :options="sources.map(s=>({label:s.displayName||s.name,value:s.name}))"/><FormKit v-model="item.args.includeUnsupportedProxy" type="checkbox" :ignore="true" label="包含不支持的节点"/><FormKit v-model="item.args.position" type="select" :ignore="true" label="添加位置" :options="{replace:'替换节点',prepend:'插入开头',append:'追加末尾'}"/></template>
<template v-else><FormKit v-if="item.type==='Regex Filter'" v-model="item.args.keep" type="checkbox" :ignore="true" label="保留匹配节点"/><FormKit v-if="item.type==='Regex Sort Operator'" v-model="item.args.order" type="select" :ignore="true" label="排序方向" :options="{asc:'升序',desc:'降序'}"/><template v-if="item.type==='Regex Rename Operator'"><div v-for="(rule,n) in item.args" :key="n" class="resource-row"><FormKit v-model="rule.expr" :ignore="true" label="正则表达式"/><FormKit v-model="rule.now" :ignore="true" label="替换文本"/><IconButton label="删除规则" icon="faTrashCan" @activate="item.args.splice(n,1)"/></div><button type="button" class="button" @click="item.args.push({expr:'',now:''})">添加规则</button></template><FormKit v-else type="textarea" :ignore="true" label="正则规则（每行一个，按行排序）" :model-value="(item.type==='Regex Filter'?item.args.regex:item.type==='Regex Sort Operator'?item.args.expressions:item.args).join('\n')" @input="lines(item,item.type==='Regex Filter'?'regex':item.type==='Regex Sort Operator'?'expressions':null,$event)"/></template>
</div></article><div class="processor-add"><label class="sr-only" for="processor-type">加工类型</label><select id="processor-type" v-model="selected"><option value="" disabled>选择加工类型</option><option v-for="[key,meta] in types" :value="key" :key="key">{{meta.label}}</option></select><IconButton label="添加加工步骤" icon="faPlus" @activate="add"/></div><details><summary>导入加工配置</summary><FormKit v-model="clipboard" type="textarea" :ignore="true" label="加工配置 JSON"/><button type="button" class="button" @click="paste">导入</button></details><p v-if="status" class="resource-status" role="status">{{status}}</p></section></template>
